changeSet.sql:
CREATE TABLE questions (
    id UUID PRIMARY KEY,
    title TEXT NOT NULL,
    body TEXT,
    status VARCHAR(20) NOT NULL DEFAULT 'OPEN' CHECK (status IN ('OPEN', 'ANSWERED', 'CLOSED')),
    asked_by UUID,
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_questions_status_created
    ON questions(status, created_at DESC);
CREATE INDEX idx_questions_asked_by
    ON questions(asked_by) WHERE asked_by IS NOT NULL;

rollback.sql:
DROP INDEX IF EXISTS idx_questions_asked_by;
DROP INDEX IF EXISTS idx_questions_status_created;
DROP TABLE questions;
